import { launch } from '/www/server/nodejs/v22.22.2/lib/node_modules/cloakbrowser/dist/index.js';

const browser = await launch({ headless: true });
const page = await browser.newPage();

// Set a realistic user agent
await page.setExtraHTTPHeaders({});

// Navigate to the WeChat article
const url = 'https://mp.weixin.qq.com/s/SAobDxFkBwAw2U25ztZOgg';
await page.goto(url, { waitUntil: 'networkidle0', timeout: 30000 });

// Wait for content to load
await page.waitForTimeout(3000);

// Get the page title
const title = await page.title();

// Get article content - try multiple selectors
let content = '';
try {
  // Common WeChat article content selectors
  const articleSection = await page.$('#js_content');
  if (articleSection) {
    content = await articleSection.innerText();
  }
} catch(e) {
  content = 'Could not extract article content';
}

// Also get the full HTML for analysis
const html = await page.content();

await browser.close();

console.log('TITLE:', title);
console.log('---CONTENT---');
console.log(content.substring(0, 8000));
if (content.length > 8000) {
  console.log('...(内容过长，已截断前8000字符)...');
}
EOF

